// Evento real que o CloudWatch emite quando a cota de INVOCAÇÃO do
// Bedrock (nao a de orcamento) e atingida numa conta especifica --
// aqui, a conta Catalogo, isolada da conta Atendimento.
{
  "source": "aws.bedrock",
  "detail-type": "Bedrock Model Invocation Throttled",
  "account": "333300000095",
  "region": "us-east-1",
  "time": "2026-08-04T14:41:07Z",
  "detail": {
    "modelId": "anthropic.claude-haiku-4-5",
    "reason": "InvocationThrottled",
    "accountUtilizationPercent": 97.4
  }
}
// Repare no "account": e a conta 333300000095 (Catalogo) sozinha --
// nenhum evento equivalente aparece na conta 333300000091
// (Atendimento) na mesma janela.

# contas-por-time.tf -- referencia as contas provisionadas pelo
# Account Factory (console ou produto do Service Catalog). NAO cria
# `aws_organizations_account` direto -- mesma decisao do L56.

variable "conta_atendimento_id" {
  type        = string
  description = "333300000091 -- conta do time Atendimento, ja na OU Producao"
}
variable "conta_extracao_id" {
  type        = string
  description = "333300000092 -- conta do time Extracao"
}
variable "conta_busca_id" {
  type        = string
  description = "333300000094 -- conta do time Busca"
}
variable "conta_catalogo_id" {
  type        = string
  description = "333300000095 -- conta do time Catalogo, a que dispara o job de lote"
}

# As quatro contas ja herdam a SCP da OU Producao publicada no L43 --
# nenhuma linha de policy precisa ser reescrita para elas. O bloco
# abaixo so documenta o mapa time -> conta, usado pelos budgets e pelo
# Identity Center nos proximos dois arquivos.
locals {
  contas_por_time = {
    atendimento = var.conta_atendimento_id
    extracao    = var.conta_extracao_id
    busca       = var.conta_busca_id
    catalogo    = var.conta_catalogo_id
  }
}

# budgets-por-time.tf -- um budget por conta vinculada, criado a
# partir da conta de gestao (paying account). Alarme em 80% do teto
# mensal declarado para cada time -- nao bloqueia gasto, so avisa.

resource "aws_sns_topic" "alarme_orcamento_ia" {
  name = "cadencia-alarme-orcamento-times-ia"
}

# teto mensal declarado por time -- medido contra o historico de
# gasto real de cada um, nao um numero redondo escolhido no ar.
locals {
  teto_mensal_por_time = {
    atendimento = 22000
    extracao    = 8000
    busca       = 12000
    catalogo    = 12000
  }
}

resource "aws_budgets_budget" "por_time" {
  for_each = local.contas_por_time

  name         = "cadencia-${each.key}-bedrock-mensal"
  budget_type  = "COST"
  limit_amount = tostring(local.teto_mensal_por_time[each.key])
  limit_unit   = "BRL"
  time_unit    = "MONTHLY"

  # Escopa o budget a UMA conta vinculada -- e o que faz cada time
  # ter o proprio orcamento, mesmo todos sendo criados a partir da
  # mesma conta de gestao.
  cost_filter {
    name   = "LinkedAccount"
    values = [local.contas_por_time[each.key]]
  }

  notification {
    comparison_operator        = "GREATER_THAN"
    threshold                  = 80
    threshold_type             = "PERCENTAGE"
    notification_type          = "ACTUAL"
    subscriber_sns_topic_arns  = [aws_sns_topic.alarme_orcamento_ia.arn]
  }
}

// DecomporFaturaPorTime/Program.cs -- consulta GetCostAndUsage
// agrupado por LINKED_ACCOUNT, filtrado ao servico Bedrock, e
// imprime o gasto de cada time no periodo. A CONTA e a dimensao de
// agrupamento -- nao ha tag nenhuma neste codigo.

using Amazon.CostExplorer;
using Amazon.CostExplorer.Model;

var mapaContaParaTime = new Dictionary<string, string>
{
    ["333300000091"] = "Atendimento",
    ["333300000092"] = "Extração",
    ["333300000094"] = "Busca",
    ["333300000095"] = "Catálogo",
};

using var ce = new AmazonCostExplorerClient(); // roda com credencial da conta de gestão

var resposta = await ce.GetCostAndUsageAsync(new GetCostAndUsageRequest
{
    TimePeriod = new DateInterval { Start = "2026-08-01", End = "2026-09-01" },
    Granularity = Granularity.MONTHLY,
    Metrics     = new List<string> { "UnblendedCost" },
    Filter = new Expression
    {
        Dimensions = new DimensionValues
        {
            Key    = Dimension.SERVICE,
            Values = new List<string> { "Amazon Bedrock" },
        },
    },
    GroupBy = new List<GroupDefinition>
    {
        new() { Type = GroupDefinitionType.DIMENSION, Key = "LINKED_ACCOUNT" },
    },
});

decimal total = 0;
foreach (var grupo in resposta.ResultsByTime[0].Groups)
{
    var contaId = grupo.Keys[0];
    var time    = mapaContaParaTime.GetValueOrDefault(contaId, $"conta desconhecida ({contaId})");
    var custo   = decimal.Parse(grupo.Metrics["UnblendedCost"].Amount);
    total += custo;
    Console.WriteLine($"{time,-12} R$ {custo,10:N2}");
}
Console.WriteLine($"{"Total",-12} R$ {total,10:N2}");
